import * as vscode from 'vscode';
import { Config } from './config';
import { ModelSelector } from './modelSelector';

/**
 * aPaaS 常用 API 签名摘要，检测到特定前缀时注入到补全 prompt 中
 */
const APAAS_API_HINTS: Record<string, string> = {
  'df.': `df-sdk v2 API:
  df.requestWithPromise({url, method, params, headers, timeout, disableSuccessMsg, disableErrorMsg}) → .asyncThen().asyncErrorCatch()
  df.uploadWithPromise({url, params(FormData), headers, timeout})
  df.showToast({message, type, duration})
  df.page.openGlobalModal({title, message, okConfig, cancelConfig})
  df.page.openFormModal({formInfo: {formId, title, documentId, onBtnClickCallback}})
  df.page.openFormDrawer({formInfo: {formId, title, rowDocumentId, onBtnClickCallback}})
  df.page.openFormListModal({formInfo: {formId, title, currentMenu, tabId, filterParam}})
  df.getVue() df.getRouter() df.getStore() df.getEnv() df.getI18n()`,

  'formEngine.': `FormEngine API:
  formEngine.formDataControl.formValue — 表单数据
  formEngine.formDataControl.updateFormValue(value)
  formEngine.formDataControl.getFormItemByUuid(uuid)
  formEngine.formDataControl.formConfig — 表单配置
  formEngine.actionControl.executeActionWithPromise(actionCode, payload)
  formEngine.actionControl.registerAction(actionCode, action)
  formEngine.extendControl.mountedInstance(el, vm, component, Vue)
  formEngine.ruleControl.setComponentValue(compConfig, value)
  formEngine.bsEventControl.triggerFormOperation(buttonConfig)`,

  'listEngine.': `ListEngine API:
  listEngine.listDataControl.queryLists — 列表数据
  listEngine.listDataControl.selectedFormData — 选中行
  listEngine.listDataControl.tableConfig — 表格配置
  listEngine.actionControl.executeActionWithPromise(actionCode, payload)
  listEngine.engineContext.instance — {formId, appId, menuId, tenantId}`,

  'NetworkControl.': `NetworkControl API (静态方法):
  NetworkControl.globalRequest(config) — 异步请求
  NetworkControl.globalSyncRequest(config) — 同步请求
  NetworkControl.globalUpload(config, onUploadProgress)
  NetworkControl.globalDownload(config, onDownloadProgress)
  NetworkControl.apis — 所有 API 配置
  NetworkControl.token — 当前 token`,
};

export class InlineCompletionProvider implements vscode.InlineCompletionItemProvider {
  private lastRequestController: AbortController | null = null;
  private debounceTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(
    private config: Config,
    private modelSelector: ModelSelector,
  ) {}

  async provideInlineCompletionItems(
    document: vscode.TextDocument,
    position: vscode.Position,
    context: vscode.InlineCompletionContext,
    token: vscode.CancellationToken,
  ): Promise<vscode.InlineCompletionItem[] | undefined> {
    // Skip if line is empty or in a comment
    const lineText = document.lineAt(position.line).text;
    if (!lineText.trim()) return undefined;

    // Cancel previous request
    this.lastRequestController?.abort();
    this.lastRequestController = new AbortController();
    const controller = this.lastRequestController;

    // Debounce 300ms
    await new Promise<void>((resolve, reject) => {
      if (this.debounceTimer) clearTimeout(this.debounceTimer);
      this.debounceTimer = setTimeout(() => resolve(), 300);
      token.onCancellationRequested(() => reject(new Error('cancelled')));
      controller.signal.addEventListener('abort', () => reject(new Error('cancelled')));
    }).catch(() => undefined);

    if (token.isCancellationRequested || controller.signal.aborted) return undefined;

    // Build prefix/suffix context
    const prefixStart = Math.max(0, position.line - 60);
    const prefixRange = new vscode.Range(prefixStart, 0, position.line, position.character);
    const prefix = document.getText(prefixRange);

    const suffixEnd = Math.min(document.lineCount - 1, position.line + 20);
    const suffixRange = new vscode.Range(position.line, position.character, suffixEnd, document.lineAt(suffixEnd).text.length);
    const suffix = document.getText(suffixRange);

    if (!prefix.trim()) return undefined;

    // Detect aPaaS API hints
    const lineBeforeCursor = lineText.substring(0, position.character);
    let apaasHint = '';
    for (const [trigger, hint] of Object.entries(APAAS_API_HINTS)) {
      if (lineBeforeCursor.includes(trigger)) {
        apaasHint = `\n\naPaaS 平台 API 参考:\n${hint}`;
        break;
      }
    }

    // Build completion request
    const cfg = this.config.get();
    const endpoint = this.config.getEndpoint('/completions');
    const headers = this.config.getHeaders();

    const body = JSON.stringify({
      prefix,
      suffix,
      language: document.languageId,
      file_path: vscode.workspace.asRelativePath(document.uri, false),
      max_tokens: 256,
      apaas_context: apaasHint || undefined,
    });

    try {
      // 800ms timeout for responsiveness
      const timeoutId = setTimeout(() => controller.abort(), 800);

      const response = await fetch(endpoint, {
        method: 'POST',
        headers,
        body,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok || token.isCancellationRequested) return undefined;

      const data = await response.json() as any;
      const completions = data?.completions;
      if (!completions?.length) return undefined;

      return completions
        .filter((c: any) => c.text?.trim())
        .map((c: any) => new vscode.InlineCompletionItem(c.text, new vscode.Range(position, position)));

    } catch {
      // Timeout, abort, or network error — silently return nothing
      return undefined;
    }
  }
}
