import * as vscode from 'vscode';
import { LLMClient } from './llmClient';
import { ModelSelector } from './modelSelector';

/**
 * Git integration: AI-generated commit messages and diff explanation.
 */
export class GitIntegration {
  constructor(
    private llmClient: LLMClient,
    private modelSelector: ModelSelector,
  ) {}

  registerCommands(context: vscode.ExtensionContext): void {
    context.subscriptions.push(
      vscode.commands.registerCommand('ruijing-ai.generateCommitMessage', () => this.generateCommitMessage()),
      vscode.commands.registerCommand('ruijing-ai.explainDiff', () => this.explainDiff()),
    );
  }

  /**
   * Generate commit message from staged changes.
   */
  private async generateCommitMessage(): Promise<void> {
    const folders = vscode.workspace.workspaceFolders;
    if (!folders?.length) {
      vscode.window.showWarningMessage('请先打开一个工作区');
      return;
    }

    const cwd = folders[0].uri.fsPath;

    await vscode.window.withProgress(
      { location: vscode.ProgressLocation.Notification, title: '睿鲸AI: 正在生成 commit message...' },
      async () => {
        try {
          // Get staged diff
          let diff = await this.runGit(cwd, ['diff', '--cached', '--stat']);
          const detailedDiff = await this.runGit(cwd, ['diff', '--cached']);

          if (!diff.trim() && !detailedDiff.trim()) {
            // No staged changes, try unstaged
            diff = await this.runGit(cwd, ['diff', '--stat']);
            if (!diff.trim()) {
              vscode.window.showWarningMessage('没有检测到代码变更');
              return;
            }
          }

          // Use fast model for commit message (Qwen/DeepSeek)
          const model = this.modelSelector.resolve(false); // Chat model = fast
          const result = await this.llmClient.complete({
            model,
            messages: [
              {
                role: 'system',
                content: `你是一个 Git commit message 生成助手。根据 diff 生成简洁的中文 commit message。
格式要求：type(scope): 描述
type: feat/fix/refactor/style/docs/test/chore
scope: 改动涉及的模块（可选）
描述: 一句话说明改了什么（不超过 50 字）

只输出 commit message，不要其他内容。`,
              },
              {
                role: 'user',
                content: `文件变更统计：\n${diff.slice(0, 1000)}\n\n详细 diff（前 3000 字符）：\n${detailedDiff.slice(0, 3000)}`,
              },
            ],
            maxTokens: 200,
          });

          const commitMsg = result.trim().replace(/^["']|["']$/g, '');
          if (!commitMsg) {
            vscode.window.showWarningMessage('AI 未返回 commit message');
            return;
          }

          // Try to set the commit message in SCM input box
          const gitExtension = vscode.extensions.getExtension('vscode.git');
          if (gitExtension) {
            const git = gitExtension.exports?.getAPI?.(1);
            if (git?.repositories?.length) {
              git.repositories[0].inputBox.value = commitMsg;
              vscode.window.showInformationMessage(`睿鲸AI: commit message 已填入`);
              return;
            }
          }

          // Fallback: copy to clipboard
          await vscode.env.clipboard.writeText(commitMsg);
          vscode.window.showInformationMessage(`睿鲸AI: commit message 已复制到剪贴板: ${commitMsg}`);

        } catch (err: any) {
          vscode.window.showErrorMessage(`生成 commit message 失败: ${err.message}`);
        }
      },
    );
  }

  /**
   * Explain current diff via Chat.
   */
  private async explainDiff(): Promise<void> {
    const folders = vscode.workspace.workspaceFolders;
    if (!folders?.length) return;

    const cwd = folders[0].uri.fsPath;

    try {
      let diff = await this.runGit(cwd, ['diff', '--cached']);
      if (!diff.trim()) {
        diff = await this.runGit(cwd, ['diff']);
      }
      if (!diff.trim()) {
        vscode.window.showWarningMessage('没有检测到代码变更');
        return;
      }

      const message = `请解释以下代码变更的内容和目的：\n\n\`\`\`diff\n${diff.slice(0, 6000)}\n\`\`\``;
      await vscode.commands.executeCommand('workbench.action.chat.open', {
        query: `@ruijing ${message}`,
      });

    } catch (err: any) {
      vscode.window.showErrorMessage(`获取 diff 失败: ${err.message}`);
    }
  }

  private runGit(cwd: string, args: string[]): Promise<string> {
    return new Promise((resolve, reject) => {
      const cp = require('child_process');
      cp.execFile('git', args, { cwd, maxBuffer: 1024 * 1024 }, (err: any, stdout: string, stderr: string) => {
        if (err && !stdout) {
          reject(new Error(stderr || err.message));
          return;
        }
        resolve(stdout || '');
      });
    });
  }
}
