import * as vscode from 'vscode';
import { ChatHandler } from './chatHandler';
import { ModelSelector } from './modelSelector';
import { Config } from './config';
import { LLMClient } from './llmClient';
import { InlineCompletionProvider } from './inlineCompletionProvider';
import { DiagnosticActionProvider } from './diagnosticActionProvider';
import { TestGenerator } from './testGenerator';
import { CodeReview } from './codeReview';
import { TerminalIntegration } from './terminalIntegration';
import { GitIntegration } from './gitIntegration';

export function activate(context: vscode.ExtensionContext) {
  console.log('[RuijingAI] Extension activating...');

  const config = new Config(context);
  const llmClient = new LLMClient(config);
  const modelSelector = new ModelSelector(config);
  const handler = new ChatHandler(config, modelSelector);

  // Register ChatParticipant
  const participant = vscode.chat.createChatParticipant('ruijing-ai.chat', handler.handle.bind(handler));
  participant.iconPath = vscode.Uri.joinPath(context.extensionUri, 'icon.png');
  participant.followupProvider = handler.getFollowupProvider();

  context.subscriptions.push(participant, modelSelector);

  // Phase 1: Register InlineCompletionProvider (Tab completion)
  const inlineProvider = new InlineCompletionProvider(config, modelSelector);
  context.subscriptions.push(
    vscode.languages.registerInlineCompletionItemProvider(
      { pattern: '**' },
      inlineProvider,
    ),
  );

  // Phase 1: Register CodeActionsProvider (error diagnosis + quick fix)
  const diagnosticProvider = new DiagnosticActionProvider(config, llmClient, modelSelector);
  context.subscriptions.push(
    vscode.languages.registerCodeActionsProvider(
      { pattern: '**' },
      diagnosticProvider,
      { providedCodeActionKinds: DiagnosticActionProvider.providedCodeActionKinds },
    ),
  );
  diagnosticProvider.registerCommands(context);

  // Phase 2: Test generator
  const testGenerator = new TestGenerator(llmClient, modelSelector);
  testGenerator.registerCommands(context);

  // Phase 2: Code review
  const codeReview = new CodeReview(llmClient, modelSelector);
  codeReview.registerCommands(context);

  // Phase 2: Terminal integration
  const terminalIntegration = new TerminalIntegration();
  context.subscriptions.push(terminalIntegration);

  // Phase 2: Git integration
  const gitIntegration = new GitIntegration(llmClient, modelSelector);
  gitIntegration.registerCommands(context);

  // Load available models from backend
  modelSelector.loadModels(llmClient).catch(err => {
    console.warn('[RuijingAI] Failed to load models:', err);
  });

  console.log('[RuijingAI] Extension activated (Phase 1 + Phase 2)');
}

export function deactivate() {
  console.log('[RuijingAI] Extension deactivated');
}
