import * as vscode from 'vscode';
import { Config } from './config';
import { LLMClient } from './llmClient';
import { ModelSelector } from './modelSelector';

/**
 * CodeActions provider for AI-powered error diagnosis and quick fix.
 * Shows "睿鲸AI: 解释此错误" and "睿鲸AI: 一键修复" on Error diagnostics.
 */
export class DiagnosticActionProvider implements vscode.CodeActionProvider {
  static readonly providedCodeActionKinds = [vscode.CodeActionKind.QuickFix];

  constructor(
    private config: Config,
    private llmClient: LLMClient,
    private modelSelector: ModelSelector,
  ) {}

  provideCodeActions(
    document: vscode.TextDocument,
    range: vscode.Range | vscode.Selection,
    context: vscode.CodeActionContext,
    _token: vscode.CancellationToken,
  ): vscode.CodeAction[] {
    const errorDiagnostics = context.diagnostics.filter(
      d => d.severity === vscode.DiagnosticSeverity.Error
    );
    if (errorDiagnostics.length === 0) return [];

    const actions: vscode.CodeAction[] = [];

    for (const diag of errorDiagnostics.slice(0, 3)) {
      // Action 1: Explain error via Chat
      const explainAction = new vscode.CodeAction(
        `睿鲸AI: 解释此错误`,
        vscode.CodeActionKind.QuickFix,
      );
      explainAction.command = {
        command: 'ruijing-ai.explainDiagnostic',
        title: '解释错误',
        arguments: [document, diag],
      };
      explainAction.diagnostics = [diag];
      actions.push(explainAction);

      // Action 2: Quick fix
      const fixAction = new vscode.CodeAction(
        `睿鲸AI: 一键修复`,
        vscode.CodeActionKind.QuickFix,
      );
      fixAction.command = {
        command: 'ruijing-ai.fixDiagnostic',
        title: '一键修复',
        arguments: [document, diag],
      };
      fixAction.diagnostics = [diag];
      fixAction.isPreferred = true;
      actions.push(fixAction);
    }

    return actions;
  }

  /**
   * Register commands for explain and fix actions.
   */
  registerCommands(context: vscode.ExtensionContext): void {
    context.subscriptions.push(
      vscode.commands.registerCommand('ruijing-ai.explainDiagnostic', async (document: vscode.TextDocument, diag: vscode.Diagnostic) => {
        const message = this.buildExplainMessage(document, diag);
        // Open Chat panel and send the message
        await vscode.commands.executeCommand('workbench.action.chat.open', {
          query: `@ruijing ${message}`,
        });
      }),

      vscode.commands.registerCommand('ruijing-ai.fixDiagnostic', async (document: vscode.TextDocument, diag: vscode.Diagnostic) => {
        await this.applyQuickFix(document, diag);
      }),
    );
  }

  private buildExplainMessage(document: vscode.TextDocument, diag: vscode.Diagnostic): string {
    const ctx = this.extractContext(document, diag);
    return `请解释以下代码错误并给出修复建议：

错误信息：${diag.message}
来源：${diag.source || 'unknown'}
文件：${vscode.workspace.asRelativePath(document.uri)}
行号：${diag.range.start.line + 1}

代码上下文：
\`\`\`${document.languageId}
${ctx}
\`\`\``;
  }

  private async applyQuickFix(document: vscode.TextDocument, diag: vscode.Diagnostic): Promise<void> {
    const ctx = this.extractContext(document, diag);
    const relPath = vscode.workspace.asRelativePath(document.uri);

    await vscode.window.withProgress(
      { location: vscode.ProgressLocation.Notification, title: '睿鲸AI: 正在生成修复...' },
      async () => {
        try {
          const model = this.modelSelector.resolve(true); // Edit model (Claude Sonnet)
          const result = await this.llmClient.complete({
            model,
            messages: [
              {
                role: 'system',
                content: `你是一个代码修复助手。用户会给你一段有错误的代码和错误信息。
请只输出修复后的代码片段（不要解释，不要 markdown 标记，直接输出代码）。
只输出需要替换的那几行，不要输出整个文件。`,
              },
              {
                role: 'user',
                content: `文件：${relPath}
语言：${document.languageId}
错误信息：${diag.message}
来源：${diag.source || 'unknown'}

错误代码上下文（错误在第 ${diag.range.start.line + 1} 行）：
${ctx}

请输出修复后的代码（只输出上面这段代码的修复版本）：`,
              },
            ],
            maxTokens: 2048,
          });

          if (!result.trim()) {
            vscode.window.showWarningMessage('AI 未返回修复代码');
            return;
          }

          // Apply the fix: replace the context range with the fixed code
          const startLine = Math.max(0, diag.range.start.line - 15);
          const endLine = Math.min(document.lineCount - 1, diag.range.end.line + 15);
          const replaceRange = new vscode.Range(
            startLine, 0,
            endLine, document.lineAt(endLine).text.length,
          );

          const edit = new vscode.WorkspaceEdit();
          const cleanedResult = this.cleanCodeBlock(result);
          edit.replace(document.uri, replaceRange, cleanedResult);
          await vscode.workspace.applyEdit(edit);

          // Check if diagnostic cleared after 2 seconds
          setTimeout(async () => {
            const remaining = vscode.languages.getDiagnostics(document.uri)
              .filter(d => d.severity === vscode.DiagnosticSeverity.Error && d.message === diag.message);
            if (remaining.length === 0) {
              vscode.window.showInformationMessage('睿鲸AI: 错误已修复');
            } else {
              vscode.window.showWarningMessage('睿鲸AI: 已应用修复，但错误可能仍存在。请检查代码。');
            }
          }, 2000);

        } catch (err: any) {
          vscode.window.showErrorMessage(`睿鲸AI 修复失败: ${err.message}`);
        }
      },
    );
  }

  private extractContext(document: vscode.TextDocument, diag: vscode.Diagnostic): string {
    const startLine = Math.max(0, diag.range.start.line - 15);
    const endLine = Math.min(document.lineCount - 1, diag.range.end.line + 15);
    const lines: string[] = [];
    for (let i = startLine; i <= endLine; i++) {
      const prefix = i === diag.range.start.line ? '>>> ' : '    ';
      lines.push(`${prefix}${i + 1}: ${document.lineAt(i).text}`);
    }
    return lines.join('\n');
  }

  private cleanCodeBlock(text: string): string {
    // Remove markdown code fences if present
    let cleaned = text.trim();
    const fenceMatch = cleaned.match(/^```[\w]*\n?([\s\S]*?)```$/);
    if (fenceMatch) {
      cleaned = fenceMatch[1].trim();
    }
    // Remove line number prefixes (e.g., ">>> 15: " or "    15: ")
    cleaned = cleaned.replace(/^(?:>>> |    )\d+: /gm, '');
    return cleaned;
  }
}
