import * as vscode from 'vscode';
import { LLMClient } from './llmClient';
import { ModelSelector } from './modelSelector';

/**
 * Generate unit tests for selected code.
 * Detects test framework from project config and generates aPaaS-aware tests.
 */
export class TestGenerator {
  constructor(
    private llmClient: LLMClient,
    private modelSelector: ModelSelector,
  ) {}

  registerCommands(context: vscode.ExtensionContext): void {
    context.subscriptions.push(
      vscode.commands.registerCommand('ruijing-ai.generateTest', () => this.generate()),
    );
  }

  private async generate(): Promise<void> {
    const editor = vscode.window.activeTextEditor;
    if (!editor) {
      vscode.window.showWarningMessage('请先打开一个文件并选中要测试的代码');
      return;
    }

    const selection = editor.selection;
    const selectedText = editor.document.getText(selection);
    if (!selectedText.trim()) {
      vscode.window.showWarningMessage('请选中要生成测试的函数或代码');
      return;
    }

    const filePath = vscode.workspace.asRelativePath(editor.document.uri, false);
    const language = editor.document.languageId;

    // Detect test framework
    const framework = await this.detectTestFramework();

    // Extract imports from the file
    const fullText = editor.document.getText();
    const importLines = fullText.split('\n')
      .filter(line => /^(import |const .+ = require|from )/.test(line.trim()))
      .join('\n');

    await vscode.window.withProgress(
      { location: vscode.ProgressLocation.Notification, title: '睿鲸AI: 正在生成单元测试...' },
      async () => {
        try {
          const model = this.modelSelector.resolve(true);
          const result = await this.llmClient.complete({
            model,
            messages: [
              { role: 'system', content: this.buildSystemPrompt(framework, language) },
              { role: 'user', content: this.buildUserPrompt(selectedText, filePath, language, importLines) },
            ],
            maxTokens: 4096,
          });

          if (!result.trim()) {
            vscode.window.showWarningMessage('AI 未返回测试代码');
            return;
          }

          // Determine test file path
          const testPath = this.inferTestFilePath(filePath, language);
          const testContent = this.cleanCodeBlock(result);

          // Create/open test file
          const folders = vscode.workspace.workspaceFolders;
          if (!folders?.length) return;

          const testUri = vscode.Uri.joinPath(folders[0].uri, testPath);
          const edit = new vscode.WorkspaceEdit();
          edit.createFile(testUri, { overwrite: false, ignoreIfExists: true });
          await vscode.workspace.applyEdit(edit);

          // Write content
          const doc = await vscode.workspace.openTextDocument(testUri);
          const existingContent = doc.getText();
          const writeEdit = new vscode.WorkspaceEdit();
          if (existingContent.trim()) {
            // Append to existing test file
            const lastLine = doc.lineCount - 1;
            const pos = new vscode.Position(lastLine, doc.lineAt(lastLine).text.length);
            writeEdit.insert(testUri, pos, '\n\n' + testContent);
          } else {
            writeEdit.insert(testUri, new vscode.Position(0, 0), testContent);
          }
          await vscode.workspace.applyEdit(writeEdit);

          // Open the test file
          await vscode.window.showTextDocument(testUri);
          vscode.window.showInformationMessage(`睿鲸AI: 测试已生成到 ${testPath}`);

        } catch (err: any) {
          vscode.window.showErrorMessage(`测试生成失败: ${err.message}`);
        }
      },
    );
  }

  private buildSystemPrompt(framework: string, language: string): string {
    return `你是一个专业的单元测试生成助手，专注于得帆 aPaaS 低代码平台开发。
测试框架：${framework}
语言：${language}

要求：
- 生成完整可运行的测试文件
- 覆盖正常路径和边界情况
- 对于 aPaaS 组件，mock 以下常用依赖：
  - df.requestWithPromise → jest.fn() 返回 Promise
  - df.showToast → jest.fn()
  - FormWidgetMixin 的 this.formValue / this.formEngine → mock 对象
  - NetworkControl.globalRequest → jest.fn()
- 使用中文注释说明每个测试用例的意图
- 只输出代码，不要解释`;
  }

  private buildUserPrompt(code: string, filePath: string, language: string, imports: string): string {
    return `为以下代码生成单元测试：

文件路径：${filePath}
语言：${language}

import 语句：
${imports}

要测试的代码：
\`\`\`${language}
${code}
\`\`\``;
  }

  private async detectTestFramework(): Promise<string> {
    const folders = vscode.workspace.workspaceFolders;
    if (!folders?.length) return 'jest';

    // Check for common test config files
    const configs = [
      { pattern: '**/jest.config.*', framework: 'jest' },
      { pattern: '**/vitest.config.*', framework: 'vitest' },
      { pattern: '**/karma.conf.*', framework: 'karma + jasmine' },
      { pattern: '**/pom.xml', framework: 'JUnit 5' },
    ];

    for (const cfg of configs) {
      const files = await vscode.workspace.findFiles(cfg.pattern, '**/node_modules/**', 1);
      if (files.length > 0) return cfg.framework;
    }

    // Default based on package.json
    try {
      const pkgFiles = await vscode.workspace.findFiles('package.json', '**/node_modules/**', 1);
      if (pkgFiles.length) {
        const bytes = await vscode.workspace.fs.readFile(pkgFiles[0]);
        const pkg = JSON.parse(Buffer.from(bytes).toString('utf-8'));
        const deps = { ...pkg.devDependencies, ...pkg.dependencies };
        if (deps['vitest']) return 'vitest';
        if (deps['jest']) return 'jest';
        if (deps['mocha']) return 'mocha';
      }
    } catch {}

    return 'jest';
  }

  private inferTestFilePath(filePath: string, language: string): string {
    const ext = language === 'java' ? '.java' : filePath.match(/\.\w+$/)?.[0] || '.js';
    const baseName = filePath.replace(/\.\w+$/, '');

    // Common test directory patterns
    if (language === 'java') {
      return baseName.replace('src/main/', 'src/test/') + 'Test' + ext;
    }
    // JS/TS/Vue: put tests in __tests__ or .test file
    const dir = baseName.split('/').slice(0, -1).join('/');
    const name = baseName.split('/').pop() || 'test';
    return `${dir}/__tests__/${name}.test${ext === '.vue' ? '.js' : ext}`;
  }

  private cleanCodeBlock(text: string): string {
    let cleaned = text.trim();
    const fenceMatch = cleaned.match(/^```[\w]*\n?([\s\S]*?)```$/);
    if (fenceMatch) cleaned = fenceMatch[1].trim();
    return cleaned;
  }
}
