import * as vscode from 'vscode';

/**
 * Terminal integration: detect errors in terminal output and offer AI analysis.
 * Monitors terminal output for error patterns and prompts user to analyze.
 */
export class TerminalIntegration implements vscode.Disposable {
  private disposables: vscode.Disposable[] = [];
  private errorBuffer: string[] = [];
  private lastNotifyTime = 0;
  private static readonly NOTIFY_COOLDOWN = 15_000; // 15s between notifications

  // Error patterns to detect
  private static readonly ERROR_PATTERNS = [
    /Error:/i,
    /ERR!/,
    /FAILED/i,
    /BUILD FAILED/i,
    /SyntaxError/,
    /TypeError/,
    /ReferenceError/,
    /ENOENT/,
    /EISDIR/,
    /EACCES/,
    /npm ERR/i,
    /FATAL/i,
    /Exception/,
    /Traceback/,
    /at\s+\S+\s+\(\S+:\d+:\d+\)/, // stack trace
    /^\s*at\s+/, // continuation stack frame
    /command not found/,
    /Cannot find module/,
    /Module not found/,
    /spawn\s+\S*\s+ENOENT/,
  ];

  // df-apaas-cli specific errors
  private static readonly APAAS_ERROR_HINTS: Record<string, string> = {
    'EISDIR': 'df-apaas-cli build 路径可能含空格，建议将 workspace 移到无空格路径',
    'spawn UNKNOWN': '可能是 Chromium 路径未配置，需设置 DF_APAAS_CLI_CHROMIUM_PATH 环境变量',
    'ETARGET': 'npm 包版本不匹配，检查 package.json 中的依赖版本',
    'registry.dfy.definesys.cn': '私有 npm registry 连接失败，检查网络或 registry 配置',
    'df-apaas-cli: command not found': '需要安装 @x-apaas/df-apaas-cli: npm i -g @x-apaas/df-apaas-cli',
  };

  constructor() {
    // Listen to terminal data writes (proposed API, may not be available)
    try {
      const win = vscode.window as any;
      if (typeof win.onDidWriteTerminalData === 'function') {
        const listener = win.onDidWriteTerminalData((event: any) => {
          this.onTerminalData(event.data);
        });
        this.disposables.push(listener);
        console.log('[RuijingAI] Terminal data listener active');
      } else {
        console.log('[RuijingAI] onDidWriteTerminalData not available, terminal error detection limited to exit codes');
      }
    } catch {
      console.warn('[RuijingAI] Terminal data listener not available');
    }

    // Also listen to terminal close for error detection
    this.disposables.push(
      vscode.window.onDidCloseTerminal(terminal => {
        if (terminal.exitStatus && terminal.exitStatus.code !== 0) {
          this.offerAnalysis(`进程退出码: ${terminal.exitStatus.code}`);
        }
      }),
    );
  }

  private onTerminalData(data: string): void {
    // Accumulate recent lines
    const lines = data.split(/\r?\n/);
    for (const line of lines) {
      if (line.trim()) {
        this.errorBuffer.push(line);
        if (this.errorBuffer.length > 150) {
          this.errorBuffer.shift();
        }
      }
    }

    // Check for error patterns
    for (const pattern of TerminalIntegration.ERROR_PATTERNS) {
      if (pattern.test(data)) {
        this.offerAnalysis(data.slice(0, 200));
        break;
      }
    }
  }

  private async offerAnalysis(errorSnippet: string): Promise<void> {
    // Rate limit notifications
    const now = Date.now();
    if (now - this.lastNotifyTime < TerminalIntegration.NOTIFY_COOLDOWN) return;
    this.lastNotifyTime = now;

    // Check for known aPaaS-specific errors
    let apaasHint = '';
    for (const [pattern, hint] of Object.entries(TerminalIntegration.APAAS_ERROR_HINTS)) {
      if (errorSnippet.includes(pattern) || this.errorBuffer.some(l => l.includes(pattern))) {
        apaasHint = `\n\n提示：${hint}`;
        break;
      }
    }

    const choice = await vscode.window.showWarningMessage(
      `检测到终端错误，是否让 AI 分析？${apaasHint ? ' (已识别为 aPaaS 相关错误)' : ''}`,
      '分析错误',
      '忽略',
    );

    if (choice !== '分析错误') return;

    // Collect recent terminal output
    const recentOutput = this.errorBuffer.slice(-100).join('\n');

    // Build analysis message and send to Chat
    let message = `请分析以下终端错误输出并给出修复建议：\n\n\`\`\`\n${recentOutput.slice(0, 4000)}\n\`\`\``;
    if (apaasHint) {
      message += `\n\n${apaasHint}`;
    }

    // Also include project context
    try {
      const pkgFiles = await vscode.workspace.findFiles('package.json', '**/node_modules/**', 1);
      if (pkgFiles.length) {
        const bytes = await vscode.workspace.fs.readFile(pkgFiles[0]);
        const pkg = JSON.parse(Buffer.from(bytes).toString('utf-8'));
        message += `\n\n项目信息：\nname: ${pkg.name}\nscripts: ${JSON.stringify(pkg.scripts || {}).slice(0, 300)}`;
      }
    } catch {}

    await vscode.commands.executeCommand('workbench.action.chat.open', {
      query: `@ruijing ${message}`,
    });
  }

  dispose(): void {
    for (const d of this.disposables) d.dispose();
  }
}
