import * as vscode from 'vscode';
import { LLMClient } from './llmClient';
import { ModelSelector } from './modelSelector';

/**
 * AI-powered code review: quality, performance, and aPaaS compliance.
 */
export class CodeReview {
  constructor(
    private llmClient: LLMClient,
    private modelSelector: ModelSelector,
  ) {}

  registerCommands(context: vscode.ExtensionContext): void {
    context.subscriptions.push(
      vscode.commands.registerCommand('ruijing-ai.reviewCode', () => this.review()),
    );
  }

  private async review(): Promise<void> {
    const editor = vscode.window.activeTextEditor;
    if (!editor) {
      vscode.window.showWarningMessage('请先打开一个文件并选中要审查的代码');
      return;
    }

    const selection = editor.selection;
    let codeToReview: string;
    let range: vscode.Range;

    if (selection.isEmpty) {
      // Review entire visible range
      const visibleRanges = editor.visibleRanges;
      range = visibleRanges[0] || new vscode.Range(0, 0, editor.document.lineCount - 1, 0);
      codeToReview = editor.document.getText(range);
    } else {
      range = selection;
      codeToReview = editor.document.getText(selection);
    }

    if (!codeToReview.trim()) {
      vscode.window.showWarningMessage('没有可审查的代码');
      return;
    }

    const filePath = vscode.workspace.asRelativePath(editor.document.uri, false);
    const language = editor.document.languageId;

    await vscode.window.withProgress(
      { location: vscode.ProgressLocation.Notification, title: '睿鲸AI: 正在审查代码...' },
      async () => {
        try {
          const model = this.modelSelector.resolve(true);
          const result = await this.llmClient.complete({
            model,
            messages: [
              { role: 'system', content: REVIEW_SYSTEM_PROMPT },
              {
                role: 'user',
                content: `审查以下代码：

文件：${filePath}
语言：${language}
行号范围：${range.start.line + 1}-${range.end.line + 1}

\`\`\`${language}
${codeToReview.slice(0, 8000)}
\`\`\``,
              },
            ],
            maxTokens: 4096,
          });

          if (!result.trim()) {
            vscode.window.showInformationMessage('睿鲸AI: 代码审查未发现问题');
            return;
          }

          // Show review in Chat panel
          await vscode.commands.executeCommand('workbench.action.chat.open', {
            query: `@ruijing 代码审查结果（${filePath}）：\n\n${result}`,
          });

        } catch (err: any) {
          vscode.window.showErrorMessage(`代码审查失败: ${err.message}`);
        }
      },
    );
  }
}

const REVIEW_SYSTEM_PROMPT = `你是得帆 aPaaS 低代码平台的代码审查专家。请从三个维度审查代码：

## 1. 通用质量
- 代码复杂度是否过高（圈复杂度 > 10 的函数）
- 重复代码
- 命名是否清晰
- 错误处理是否完善
- 潜在的 null/undefined 风险

## 2. 性能
- 不必要的重复渲染（Vue computed vs watch 使用不当）
- 内存泄漏（事件监听未清理、定时器未清除）
- 大数组操作（map/filter 链过长）
- 不必要的 API 调用

## 3. aPaaS 平台规范
- 是否使用 df-sdk v2 标准 API（df.requestWithPromise 而非直接 axios）
- 是否正确使用组件 Mixin（FormWidgetMixin 的 formValue 双向绑定）
- componentModelField 配置是否完整
- 国际化是否使用 df.getI18n().t() 而非硬编码中文
- 是否遵循脚手架目录结构约定

## 输出格式
对每个发现的问题，输出：
- **问题**：简述问题
- **位置**：行号或代码片段
- **建议**：修复方案
- **修复代码**：如果能给出具体修复代码（用 \`\`\` 包裹）

如果代码质量良好，输出"代码质量良好，未发现明显问题"。`;
